import{_ as p,a0 as o,w as r,s as u,I as i,x as n,a1 as s,A as e,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux Mint 20 发布前一窥 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Mint 20 发布前一窥 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Mint 20 发布前一窥 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Mint 20 发布前一窥 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200525 Linux Mint 20- Release Date, Features and Everything Important Associated With it","title":"Linux Mint 20 发布前一窥","tag":"202006","desc":""},"relativePath":"202006/20200525 Linux Mint 20- Release Date, Features and Everything Important Associated With it.md","filePath":"[post].md"}'),m={name:"202006/20200525 Linux Mint 20- Release Date, Features and Everything Important Associated With it.md"};function d(x,t,f,L,b,h){const a=o("Link");return r(),u("div",null,[t[30]||(t[30]=i("h1",{id:"linux-mint-20-发布前一窥",tabindex:"-1"},[n("Linux Mint 20 发布前一窥 "),i("a",{class:"header-anchor",href:"#linux-mint-20-发布前一窥","aria-label":"Permalink to “Linux Mint 20 发布前一窥”"},"​")],-1)),i("p",null,[s(a,{href:"https://itsfoss.com/ubuntu-20-04-release-features/"},{default:e(()=>[...t[0]||(t[0]=[n("Ubuntu 20.04 LTS 版本发布了",-1)])]),_:1}),t[1]||(t[1]=n("。这对 Linux Mint 用户来说也是一个好消息。一个新的 Ubuntu LTS 版本意味着新的 Linux Mint 主要版本也将很快随之出现。",-1))]),t[31]||(t[31]=i("p",null,"为什么这么说呢？因为 Linux Mint 是基于 Ubuntu 的长期支持（LTS）版本的。Mint 18 系列是基于 Ubuntu 16.04 LTS，Mint 19 是基于 Ubuntu 18.04 LTS 等等。",-1)),i("p",null,[t[3]||(t[3]=n("与 Ubuntu 不同，Linux Mint 没有固定的发布时间表。根据以往的趋势，我可以做出一个明智的猜测，",-1)),s(a,{href:"https://www.linuxmint.com/"},{default:e(()=>[...t[2]||(t[2]=[n("Linux Mint",-1)])]),_:1}),t[4]||(t[4]=n(" 20 应该会在今年 6 月发布。",-1))]),t[32]||(t[32]=l('<h3 id="linux-mint-20-ulyana-即将推出的新功能" tabindex="-1">Linux Mint 20 “Ulyana” 即将推出的新功能 <a class="header-anchor" href="#linux-mint-20-ulyana-即将推出的新功能" aria-label="Permalink to “Linux Mint 20 “Ulyana” 即将推出的新功能”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/04/Linux-Mint-20.png?ssl=1" alt=""></p><p>让我们来看看代号为 Ulyana 的 Linux Mint 20 中提出的一些主要新功能和变化。</p><h4 id="_1-提高-nemo-文件管理器的性能" tabindex="-1">1. 提高 Nemo 文件管理器的性能 <a class="header-anchor" href="#_1-提高-nemo-文件管理器的性能" aria-label="Permalink to “1. 提高 Nemo 文件管理器的性能”">​</a></h4><p>Nemo 文件管理器计划中的性能改进之一是它处理缩略图的方式。你可能还没有意识到，但缩略图的生成需要相当多的系统资源（以及磁盘空间）。试着打开一个有几千张图片的文件夹，你会发现 CPU 的消耗会上升。</p><p>在 Linux Mint 20 中，其目标是优先考虑内容和导航，并尽可能地延迟缩略图的渲染。这意味着在缩略图渲染之前，文件夹的内容会以通用图标显示出来。这不会让人觉得赏心悦目，但你会注意到性能的改善。</p><h4 id="_2-两种焕然一新的颜色变体" tabindex="-1">2. 两种焕然一新的颜色变体 <a class="header-anchor" href="#_2-两种焕然一新的颜色变体" aria-label="Permalink to “2. 两种焕然一新的颜色变体”">​</a></h4><p>默认情况下，Linux Mint 是绿色/薄荷色的风格。还有一些其它的颜色点缀。Linux Mint 20 新添加了两种可爱的的粉红色和青蓝色。</p><p>以及新的青蓝色风格：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/04/mint-20-aqua.jpg?ssl=1" alt="Linux Mint Aqua"></p><p>这里是新的粉红色风格：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/04/mint-20-pink-1.jpg?ssl=1" alt="Linux Mint Pink"></p><h4 id="_3-没有过度偏重于-snap-包" tabindex="-1">3. 没有过度偏重于 Snap 包 <a class="header-anchor" href="#_3-没有过度偏重于-snap-包" aria-label="Permalink to “3. 没有过度偏重于 Snap 包”">​</a></h4><p>Ubuntu 20.04 将 snap 包的优先级放在了通常的 apt 包之前。事实上，如果你在 Ubuntu 20.04 中使用 <code>apt</code> 命令安装 Chromium 浏览器时，它会自动安装 snap 版本。</p><p>Linux Mint 团队显然对此不满意，他们确认 Mint 20 将不会安装 snaps 或 snapd。它还将禁止 <code>apt</code> 使用 snapd。</p><p>你仍然可以自己手动安装 snap 包。只是不会由 <code>apt</code> 来安装它们。</p><h4 id="_4-有了这个新工具-跨网络共享文件变得很简单。" tabindex="-1">4. 有了这个新工具，跨网络共享文件变得很简单。 <a class="header-anchor" href="#_4-有了这个新工具-跨网络共享文件变得很简单。" aria-label="Permalink to “4. 有了这个新工具，跨网络共享文件变得很简单。”">​</a></h4>',17)),i("p",null,[t[6]||(t[6]=n("Linux Mint 20 将提供一个",-1)),s(a,{href:"https://blog.linuxmint.com/?p=3863"},{default:e(()=>[...t[5]||(t[5]=[n("新的 GUI 工具",-1)])]),_:1}),t[7]||(t[7]=n("，可以轻松地在本地网络上共享文件，而无需任何额外的配置。",-1))]),t[33]||(t[33]=i("p",null,[i("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/04/mint-20-warpinator-1.png?ssl=1",alt:"New tool for sharing files across the network"})],-1)),t[34]||(t[34]=i("h4",{id:"_5-更好地整合了-electron-应用程序的桌面",tabindex:"-1"},[n("5. 更好地整合了 Electron 应用程序的桌面 "),i("a",{class:"header-anchor",href:"#_5-更好地整合了-electron-应用程序的桌面","aria-label":"Permalink to “5. 更好地整合了 Electron 应用程序的桌面”"},"​")],-1)),i("p",null,[s(a,{href:"https://www.electronjs.org/"},{default:e(()=>[...t[8]||(t[8]=[n("Electron",-1)])]),_:1}),t[10]||(t[10]=n(" 是一个开源框架，它允许使用 Web 技术构建跨平台的桌面应用程序。有些人称它为懒惰的方法，因为应用程序运行在 Chromium 浏览器之上。然而，这可以让开发人员轻松地将他们的应用程序提供给 Linux（和 macOS）。",-1)),s(a,{href:"https://itsfoss.com/slack-use-linux/"},{default:e(()=>[...t[9]||(t[9]=[n("Linux 上的 Slack",-1)])]),_:1}),t[11]||(t[11]=n(" 就是众多这样的例子之一。",-1))]),t[35]||(t[35]=l('<p>Linux Mint 20 将对 Electron 应用提供更好的支持，并改进系统托盘和桌面通知的集成。</p><h4 id="_6-改进的支持多显示器的比例缩放功能" tabindex="-1">6. 改进的支持多显示器的比例缩放功能 <a class="header-anchor" href="#_6-改进的支持多显示器的比例缩放功能" aria-label="Permalink to “6. 改进的支持多显示器的比例缩放功能”">​</a></h4><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/04/monitor_display_Linux_mint_20.png?ssl=1" alt="improved multi-monitor support"></p><p>一个提议的改变是在 Linux Mint 20 中加入支持多显示器的比例缩放功能。如果你有一个 HiDPI 和非 HiDPI 显示器的组合，你可以为它们每一个选择不同的分辨率、刷新率和不同的分数缩放。</p><p>在 Mint 20 的登录屏幕，可以让你跨多个显示器拉伸显示背景。</p><h4 id="_7-改进对-nvidia-optimus-的支持" tabindex="-1">7. 改进对 Nvidia Optimus 的支持 <a class="header-anchor" href="#_7-改进对-nvidia-optimus-的支持" aria-label="Permalink to “7. 改进对 Nvidia Optimus 的支持”">​</a></h4><p>在 Mint 20 中，Nvidia prime 小程序会显示 GPU 渲染器。你也可以直接从系统托盘中的菜单中选择切换到哪块卡。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/06/nvidia-prime-applet-linux-mint-20.png?w=386&amp;ssl=1" alt="Switch between GPUs"></p><p>你也可以使用 Nvidia “On-Demand” 模式。在这种模式下，将使用英特尔卡来渲染会话。而如视频播放器或视频编辑器这样的兼容应用程序可以在应用程序菜单中打开时使用 Nvidia GPU。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/06/nvidia-on-deman-feature-linux-mint-20.png?w=526&amp;ssl=1" alt="Run an application with NVIDIA GPU"></p><h4 id="_8-不再支持-32-位" tabindex="-1">8. 不再支持 32 位 <a class="header-anchor" href="#_8-不再支持-32-位" aria-label="Permalink to “8. 不再支持 32 位”">​</a></h4><p>虽然 Ubuntu 18.04 在两年前就放弃了 32 位 ISO，但 Linux Mint 19 系列一直提供 32 位 ISO 的下载和安装。</p><p>这种情况在 Linux Mint 20 中有所改变。Linux Mint 20 已经没有 32 位版本了。这是因为 32 位支持从 Ubuntu 20.04 中完全消失了。</p><h4 id="还有什么" tabindex="-1">还有什么？ <a class="header-anchor" href="#还有什么" aria-label="Permalink to “还有什么？”">​</a></h4><p>Cinnamon 4.6 桌面版的发布带来了很多视觉上的变化。</p>',15)),i("p",null,[t[13]||(t[13]=n("在 Ubuntu 20.04 中，应该会有一些“引擎盖下”的变化，比如 Linux Kernel 5.4，取消了 Python 2 的支持，加入 ",-1)),s(a,{href:"https://itsfoss.com/wireguard/"},{default:e(()=>[...t[12]||(t[12]=[n("Wireguard VPN",-1)])]),_:1}),t[14]||(t[14]=n(" 等。",-1))]),t[36]||(t[36]=i("p",null,"随着开发的进展，我会在本文中更新更多的功能。敬请期待。",-1)),t[37]||(t[37]=i("hr",null,null,-1)),i("p",null,[t[16]||(t[16]=n("via: ",-1)),s(a,{href:"https://itsfoss.com/linux-mint-20/"},{default:e(()=>[...t[15]||(t[15]=[n("https://itsfoss.com/linux-mint-20/",-1)])]),_:1})]),i("p",null,[t[21]||(t[21]=n("作者：",-1)),s(a,{href:"https://itsfoss.com/author/abhishek/"},{default:e(()=>[...t[17]||(t[17]=[n("Abhishek Prakash",-1)])]),_:1}),t[22]||(t[22]=n(" 选题：",-1)),s(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[18]||(t[18]=[n("lujun9972",-1)])]),_:1}),t[23]||(t[23]=n(" 译者：",-1)),s(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[19]||(t[19]=[n("wxy",-1)])]),_:1}),t[24]||(t[24]=n(" 校对：",-1)),s(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[20]||(t[20]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[27]||(t[27]=n("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[25]||(t[25]=[n("LCTT",-1)])]),_:1}),t[28]||(t[28]=n(" 原创编译，",-1)),s(a,{href:"https://linux.cn/"},{default:e(()=>[...t[26]||(t[26]=[n("Linux中国",-1)])]),_:1}),t[29]||(t[29]=n(" 荣誉推出",-1))])])}const g=p(m,[["render",d]]);export{T as __pageData,g as default};
